{
  "mechanisms": [
    {
      "name": "separate_mb_mf_betas",
      "title": "Separate MB and MF Inverse Temperatures",
      "description": "Uses distinct inverse temperature parameters for model-based and model-free values at stage 1, rather than a single temperature and a mixture weight.",
      "params": [
        {
          "name": "beta_mb",
          "bounds": [0, 10]
        },
        {
          "name": "beta_mf1",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_1 = beta_mb * q_stage1_mb + beta_mf1 * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "separate_stage2_beta",
      "title": "Separate Stage 2 Inverse Temperature",
      "description": "Uses a distinct inverse temperature parameter for stage 2 choices.",
      "params": [
        {
          "name": "beta_mf2",
          "bounds": [0, 10]
        }
      ],
      "evidence": "logits_2 = beta_mf2 * q_stage2_mf[state_idx]",
      "expressible_in_slots": true
    },
    {
      "name": "outcome_dependent_perseveration",
      "title": "Outcome-Dependent Perseveration",
      "description": "Adds a perseveration bonus to the previously chosen stage 1 action, with different parameters depending on whether the previous trial was rewarded or unrewarded.",
      "params": [
        {
          "name": "pers_win",
          "bounds": [-5, 5]
        },
        {
          "name": "pers_lose",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "if prev_r > 0:\n                logits_1[prev_a1] += pers_win\n            else:\n                logits_1[prev_a1] += pers_lose",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates stage 1 model-free values using the stage 2 reward prediction error scaled by an eligibility trace parameter.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[a1] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_decay",
      "title": "Unchosen Option Decay",
      "description": "Decays the Q-values of all unchosen actions at both stages towards zero by a decay rate parameter.",
      "params": [
        {
          "name": "unchosen_decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_a1 = 1 - a1\n        q_stage1_mf[unchosen_a1] *= (1 - unchosen_decay)\n        \n        for s in range(2):\n            for a in range(2):\n                if not (s == state_idx and a == a2):\n                    q_stage2_mf[s, a] *= (1 - unchosen_decay)",
      "expressible_in_slots": true
    }
  ]
}
